import React, { useState } from 'react';
import { Navigation, AlertCircle, Database, CheckCircle2, Clock, MapPin } from 'lucide-react';

const ScheduleTab = ({ onNavigateToReports }) => {
  const [verifyingId, setVerifyingId] = useState(null);

  // Expanded list to demonstrate scrolling
  const schedule = [
    { id: 'LOC_04', time: '08:00', area: 'Sector 4', hasReport: true, status: 'pending', type: 'Biohazard' },
    { id: 'LOC_09', time: '10:30', area: 'Zone B', hasReport: false, status: 'pending', type: 'General' },
    { id: 'LOC_12', time: '13:00', area: 'Plaza SQ', hasReport: false, status: 'done', type: 'Recycle' },
    { id: 'LOC_15', time: '15:30', area: 'East Gate', hasReport: true, status: 'pending', type: 'General' },
    { id: 'LOC_22', time: '17:00', area: 'North Hub', hasReport: false, status: 'pending', type: 'Biohazard' },
    { id: 'LOC_31', time: '19:00', area: 'South Park', hasReport: false, status: 'pending', type: 'Recycle' },
  ];

  const handleRouteClick = (area) => {
    // This now actively triggers
    alert(`🛰️ GPS SYNC: Calculating fastest route to ${area}...`);
    // In a real app, you'd use window.open(`https://maps.google.com/?q=${area}`)
  };

  return (
    <div className="w-full max-w-md h-full flex flex-col pt-10 pb-32">
      {/* HEADER - Fixed */}
      <div className="flex justify-between items-end mb-8 px-6">
        <div>
          <h3 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter">Manifest.</h3>
          <p className="text-[10px] font-black text-[#CAD23C] bg-[#47510B] inline-block px-2 py-0.5 rounded mt-1 uppercase tracking-widest">Live_Shift</p>
        </div>
        <div className="text-right">
            <span className="text-[9px] font-black opacity-30 tracking-[0.3em] block uppercase">Operator_View</span>
            <span className="text-[9px] font-black opacity-30 tracking-[0.3em] block uppercase">Grid_v2.4</span>
        </div>
      </div>

      {/* SCROLLABLE LIST AREA */}
      <div className="flex-1 overflow-y-auto no-scrollbar px-6">
        <div className="relative border-l-4 border-[#47510B]/10 ml-4 pl-8 space-y-10 pb-10">
          {schedule.map((item) => (
            <div key={item.id} className="relative">
              {/* Timeline Node */}
              <div className={`absolute -left-[42px] top-1 w-6 h-6 rounded-full border-4 border-[#FDFAD8] shadow-sm z-10 transition-colors duration-500 ${item.status === 'done' ? 'bg-[#CAD23C]' : 'bg-[#47510B]'}`} />

              <div className="group relative">
                <div className="flex items-center gap-3 mb-2">
                  <Clock size={12} className="text-[#47510B]/40" />
                  <span className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest">{item.time}</span>
                  {item.hasReport && (
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        onNavigateToReports();
                      }}
                      className="flex items-center gap-1 bg-[#AB1717] text-white px-2 py-0.5 rounded text-[8px] font-black animate-pulse"
                    >
                      <AlertCircle size={10} /> ISSUE_REPORTED
                    </button>
                  )}
                </div>

                <div className={`p-5 rounded-[30px] border-2 transition-all duration-300 flex items-center justify-between ${item.status === 'done' ? 'bg-white/40 border-dashed border-[#47510B]/10' : 'bg-white border-[#47510B] shadow-[6px_6px_0_0_#47510B] active:translate-x-1 active:translate-y-1 active:shadow-none'}`}>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                        <MapPin size={14} className={item.status === 'done' ? 'opacity-20' : 'text-[#CAD23C]'} />
                        <h4 className={`text-xl font-black uppercase italic leading-none ${item.status === 'done' ? 'opacity-20' : 'text-[#47510B]'}`}>{item.area}</h4>
                    </div>
                    <p className="text-[9px] font-bold opacity-30 mt-2 uppercase tracking-tighter">{item.type} // {item.id}</p>
                  </div>

                  {item.status === 'done' ? (
                    <CheckCircle2 size={24} className="text-[#CAD23C] opacity-40" />
                  ) : (
                    <div className="flex gap-2">
                      <button 
                        onClick={() => setVerifyingId(item.id)} 
                        className="p-3 rounded-xl bg-[#FDFAD8] text-[#47510B] border border-[#47510B]/10 hover:bg-[#CAD23C] transition-colors"
                        title="Verify Job"
                      >
                        <CheckCircle2 size={20} strokeWidth={2.5} />
                      </button>
                      <button 
                        onClick={() => handleRouteClick(item.area)} 
                        className="p-3 rounded-xl bg-[#47510B] text-[#CAD23C] shadow-lg active:scale-90 transition-all"
                        title="Open Route"
                      >
                        <Navigation size={20} strokeWidth={3} />
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ADMIN VERIFICATION MODAL */}
      {verifyingId && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#47510B]/95 backdrop-blur-md">
           <div className="bg-[#FDFAD8] p-8 rounded-[50px] border-[10px] border-white w-full max-w-sm text-center animate-slide-up shadow-2xl">
             <Database size={40} className="mx-auto text-[#47510B] mb-4 animate-bounce" />
             <h3 className="text-xl font-black uppercase italic text-[#47510B]">Admin_Sensor_Sync</h3>
             <div className="my-6 p-6 bg-white rounded-3xl border-2 border-[#47510B]">
                <p className="text-[9px] font-black opacity-30 uppercase mb-2">Sensor Verification</p>
                <div className="flex items-baseline justify-center gap-1">
                    <span className="text-5xl font-black text-[#AB1717]">04</span>
                    <span className="text-xl font-black text-[#AB1717] opacity-40">%</span>
                </div>
                <p className="text-[8px] font-black text-[#CAD23C] bg-[#47510B] px-2 py-0.5 rounded mt-3 inline-block uppercase">Threshold_Met</p>
             </div>
             <button onClick={() => setVerifyingId(null)} className="w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl active:scale-95 transition-all">
                Confirm Completion
             </button>
           </div>
         </div>
      )}
    </div>
  );
};

export default ScheduleTab;
